}
function sndBus(cat){
  var B=bus(), a=AC, S;
  if(!B||!a) return null;
  if(!SND||SND.out!==B){
    S=(B.__snd&&B.__snd.out===B)?B.__snd:sndBuild(a,B);
    if(!S) return B;
    try{ B.__snd=S; }catch(e){}
    SND=S;
  }
  return SND.bus[cat]||SND.bus.world||B;
}
